    { const c = P.I(0.8, 320, 150); P.shape(P.disc(c[0], c[1], 22, 20).map(p => [c[0] + (p[0] - c[0]) * 0.6, p[1]]), 'y6r4k3', 1); P.shape(P.disc(c[0], c[1], 8, 12).map(p => [c[0] + (p[0] - c[0]) * 0.6, p[1]]), 'y8r3', 0.6); P.line([P.I(0.8, 290, 100), P.I(0.8, 352, 196)], 1.6); }
