    for (let i = 1; i < 5; i++) P.line([P.I(bx + 60 + i * 20, by + 5, 43), P.I(bx + 60 + i * 20, by + 91, 43)], 0.9, { ink: 0, lvl: 7 });
    P.box(bx, by + 96, 0, 10, 10, 190, 'r5y5k3', 0.8); P.box(bx + 150, by + 96, 0, 10, 10, 190, 'r5y5k3', 0.8);
    P.line([P.I(bx, by + 100, 190), P.I(bx + 160, by + 100, 190)], 2.4, { ink: 3, lvl: 7, taper: 0 });
    { const pts = []; for (let i = 0; i <= 10; i++) pts.push(P.I(bx + 16 * i, by + 101, 188 - Math.sin(Math.PI * i / 10) * 24)); pts.push(P.I(bx + 160, by + 101, 196), P.I(bx, by + 101, 196)); P.shape(pts, 'y6r3k1', 0.7); }
    /* coffre, tabouret et lampe de nuit */
